.markdown-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.markdown-field__box {
    display: flex;
    flex-direction: column;
    min-height: 280px;
    padding: 4px 12px 12px;
    border: 1px solid var(--g-color-line-generic);
    border-radius: var(--g-border-radius-l);
    background: var(--g-color-base-background);
    transition: border-color 0.1s linear;
}

.markdown-field__box:hover {
    border-color: var(--g-color-line-generic-hover);
}

.markdown-field__box:focus-within {
    border-color: var(--g-color-line-generic-active);
}

.markdown-field__box_invalid,
.markdown-field__box_invalid:hover,
.markdown-field__box_invalid:focus-within {
    border-color: var(--g-color-line-danger);
}

.markdown-field__box > * {
    flex: 1 0 auto;
}

