  (globalThis as any).ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
  (window as any).matchMedia = () => ({ matches: false, addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {} });
});
it('switches to wysiwyg keeping content', async () => {
  const errs: string[] = []; const orig = console.error; console.error = (...a) => { errs.push(String(a[0])); };
  const { useMarkdownFieldEditor, MarkdownField } = await import('../src/MarkdownField');
  let ed: any;
  function T() { ed = useMarkdownFieldEditor({ initialValue: '**bold** text' }); return <MarkdownField editor={ed} label="L" />; }
  const el = document.createElement('div'); document.body.append(el);
  await act(async () => { createRoot(el).render(<ThemeProvider theme="light"><T /></ThemeProvider>); });
  await act(async () => { ed.setEditorMode('wysiwyg'); });
  const pm = el.querySelector('.ProseMirror')!;
  expect(pm.innerHTML).toContain('<strong>bold</strong>');
  expect(ed.getValue()).toBe('**bold** text');
  console.error = orig; console.log('console errors:', errs.filter(e => !e.includes('not wrapped in act')));
});
EOF
