import { describe, it, expect, beforeAll } from 'vitest';
import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { ThemeProvider } from '@gravity-ui/uikit';

beforeAll(() => {
  (globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
  const r = { left: 0, right: 0, top: 0, bottom: 0, width: 0, height: 0, x: 0, y: 0, toJSON() {} };
  (Range.prototype as any).getClientRects = () => [];
  (Range.prototype as any).getBoundingClientRect = () => r;
  (globalThis as any).ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
  (window as any).matchMedia = () => ({ matches: false, addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {} });
});

describe('App', () => {
  it('renders form with markdown editor and live preview, validates and submits', async () => {
    const { App } = await import('../src/App');
    const el = document.createElement('div'); document.body.append(el);
    await act(async () => { createRoot(el).render(<ThemeProvider theme="light"><App /></ThemeProvider>); });
    await act(async () => { await new Promise(r => setTimeout(r, 50)); });
    expect(el.querySelector('.cm-content')).toBeTruthy();
    expect(el.querySelector('.g-md-markup-preview')).toBeTruthy();

    // empty submit -> errors
    await act(async () => { (el.querySelector('button[type=submit]') as HTMLButtonElement).click(); });
    expect(el.textContent).toContain('Добавьте описание');
    expect(el.textContent).toContain('Укажите заголовок');

    // type markdown into codemirror
    const { EditorView } = await import('@codemirror/view');
    const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
    await act(async () => { view.dispatch({ changes: { from: 0, insert: '# Hi\n\n**bold** <b>x</b>' } }); });
    const preview = el.querySelector('.g-md-markup-preview .yfm')!;
    console.log('PREVIEW:', preview.innerHTML);
    expect(preview.innerHTML).toContain('<strong>bold</strong>');
    expect(preview.innerHTML).toContain('&lt;b&gt;');
    expect(el.textContent).not.toContain('Добавьте описание');

    const input = el.querySelector('#task-title') as HTMLInputElement;
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')!.set!;
    await act(async () => { setter.call(input, 'Тест'); input.dispatchEvent(new Event('input', { bubbles: true })); });
    await act(async () => { (el.querySelector('button[type=submit]') as HTMLButtonElement).click(); });
    expect(el.textContent).toContain('Отправлено: Тест');
    expect(el.querySelector('pre')!.textContent).toBe('# Hi\n\n**bold** <b>x</b>');

    await act(async () => { (el.querySelector('button[type=reset]') as HTMLButtonElement).click(); });
    expect(view.state.doc.toString()).toBe('');
    expect(input.value).toBe('');
  });
});
